WITH target AS (
 SELECT County FROM schools WHERE CDSCode = '01611430131177'
), scores AS (
 SELECT sat.cds, sat.NumGE1500
 FROM satscores sat
 WHERE sat.rtype = 'S' AND sat.NumGE1500 IS NOT NULL
), ranked AS (
 SELECT s.CDSCode, s.AdmFName1, s.AdmLName1, sc.NumGE1500,
        ROW_NUMBER() OVER (ORDER BY sc.NumGE1500 DESC, s.CDSCode ASC) AS rn
 FROM schools s JOIN target t ON s.County = t.County
 JOIN scores sc ON sc.cds = s.CDSCode
)
SELECT CDSCode, AdmFName1, AdmLName1, NumGE1500 FROM ranked WHERE rn = 1;

