WITH target_cards AS (
  SELECT uuid FROM cards WHERE name = 'Mishra''s Factory'
), latest_date AS (
  SELECT MAX(r.date) AS ruling_date
  FROM rulings r JOIN target_cards c ON c.uuid = r.uuid
)
SELECT COUNT(*) AS ruling_count
FROM rulings r
JOIN target_cards c ON c.uuid = r.uuid
JOIN latest_date d ON r.date = d.ruling_date;

